llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C03"],
      "claim": "Procainamide, a benzamide with a basic aminoethyl side chain closely analogous to the query's benzamide-morpholinoethyl scaffold, had an absolute oral bioavailability of 92% after oral vs IV administration, strongly supporting F >=20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C46"],
      "claim": "N-acetylprocainamide/acecainide, which retains the benzamide-ethylamine core, had an absolute oral bioavailability of 87.2% measured by simultaneous oral/IV stable-isotope administration, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Sematilide, a related benzamide antiarrhythmic with a basic ethylamino side chain, had absolute oral bioavailability of about 59% (with other estimates of 46-48%), still well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C48"],
      "claim": "Haloperidol, a chlorophenyl-containing basic drug with the highest Morgan similarity to the query, showed absolute oral bioavailability of 60-70% in most studies, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Indoramin, a benzamide-piperidine with substantial first-pass metabolism, had a median absolute oral bioavailability of 23.6%, just above the threshold, indicating that first-pass liability does not necessarily make F <20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Loperamide, a structurally distant piperidine opioid, has very low oral bioavailability (0.3%) due to P-gp efflux and first-pass metabolism; this is contradictory but has low transferability to the small morpholine benzamide query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a 4-chlorobenzamide with a morpholinoethyl side chain. The closest functional analogues—procainamide, N-acetylprocainamide, and sematilide—are benzamide ethylamine derivatives with absolute oral bioavailability of about 46-92%, all above the 20% threshold. Haloperidol, a chlorophenyl basic drug, also averages 35-70%. The only clearly low-F analogue, loperamide, is structurally distant and its P-gp/first-pass liabilities are not expected to apply. Thus F >=20% is better supported.",
  "evidence_gaps": [
    "No direct experimental bioavailability record for the query molecule itself was retrieved; all evidence is from analogues with Morgan similarity below 0.35.",
    "Fasted-state-specific oral bioavailability data are not explicitly reported in the retrieved records; most values are from general oral dosing studies.",
    "Some retrieved records appear to have SMILES/name mismatches (e.g., molsidomine), reducing their usability for direct transfer."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

